# Generated by manage.py generate_test_cases.
"""Verify bounded original content, discovery and real MCP transport."""

import base64
from unittest.mock import patch
from uuid import uuid4

from django.core.files.uploadedfile import SimpleUploadedFile
from django.http import HttpResponse
from django.test import override_settings
from django.urls import reverse

from bloomerp.models import FileNode
from bloomerp.router import router
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    BloomerpMcpViewTestCase,
    ExpectedResult,
    McpRequestScenario,
    RequestScenario,
)


class TestFileReadView(BloomerpAPIViewTestCase):
    """Test complete base64 originals and clear authenticated-download fallback."""

    view_name = "api_file_read"
    auto_create_customers = False

    def extendedSetup(self) -> None:
        """Store binary content with a filename independent of its storage key."""
        self.original = b"\x00\xff\x80hello"
        self.file = FileNode.objects.create(
            content=SimpleUploadedFile("original.bin", self.original),
            kind="FILE",
            created_by=self.admin_user,
            updated_by=self.admin_user,
        )

    def original_content(self, response: HttpResponse) -> bool:
        """Check metadata and byte equality without revealing internal storage URLs."""
        data = response.json()
        self.assertEqual(base64.b64decode(data["content_base64"]), self.original)
        self.assertEqual(data["content_status"], "included")
        self.assertEqual(data["size"], len(self.original))
        self.assertTrue(data["content_is_untrusted"])
        self.assertTrue(data["download_requires_authentication"])
        self.assertNotIn("bloomerp/files", str(data))
        return True

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover routed access denial and complete original content."""
        scenarios = []
        for name, user, file_id, status in [
            ("Owner reads original", self.admin_user, str(self.file.pk), 200),
            (
                "Other user cannot read metadata",
                self.normal_user,
                str(self.file.pk),
                404,
            ),
            ("Missing file", self.admin_user, str(uuid4()), 404),
            ("Invalid ID", self.admin_user, "invalid", 400),
            ("Anonymous read", None, str(self.file.pk), 401),
        ]:
            scenarios.append(
                RequestScenario(
                    name=name,
                    method="POST",
                    user=user,
                    data={"file_id": file_id},
                    content_type="application/json",
                    expected=ExpectedResult(
                        status_code=status,
                        response_validators=self.original_content
                        if status == 200
                        else [],
                    ),
                )
            )
        return scenarios

    def test_inline_boundary_and_stale_size_never_truncate(self) -> None:
        """Use actual bounded storage bytes, even when stored metadata understates size."""
        self.client.force_login(self.admin_user)
        self.file.meta["size"] = 1
        FileNode.objects.filter(pk=self.file.pk).update(meta=self.file.meta)
        for limit, status in [
            (len(self.original), "included"),
            (len(self.original) - 1, "too_large"),
        ]:
            with (
                self.subTest(limit=limit),
                override_settings(BLOOMERP_FILE_READ_MAX_BYTES=limit),
            ):
                response = self.client.post(
                    reverse(self.view_name),
                    {"file_id": str(self.file.pk)},
                    content_type="application/json",
                )
                self.assertEqual(response.status_code, 200)
                data = response.json()
                self.assertEqual(data["content_status"], status)
                self.assertEqual(data["inline_limit_bytes"], limit)
                if status == "too_large":
                    self.assertIsNone(data["content_base64"])
                    download = self.client.get(data["download_path"])
                    self.assertEqual(
                        b"".join(download.streaming_content), self.original
                    )

    def test_metadata_only_does_not_open_storage(self) -> None:
        """Allow callers to inspect permitted metadata without fetching any bytes."""
        self.client.force_login(self.admin_user)
        storage = FileNode._meta.get_field("content").storage
        with patch.object(
            storage, "open", side_effect=AssertionError("Must not open storage")
        ):
            response = self.client.post(
                reverse(self.view_name),
                {"file_id": str(self.file.pk), "include_content": False},
                content_type="application/json",
            )
        self.assertEqual(response.status_code, 200, response.content)
        self.assertEqual(response.json()["content_status"], "not_requested")
        self.assertIsNone(response.json()["content_base64"])

    def test_missing_storage_has_generic_unavailable_error(self) -> None:
        """Do not expose storage paths or internal exception details on missing bytes."""
        self.client.force_login(self.admin_user)
        storage = FileNode._meta.get_field("content").storage
        with patch.object(
            storage, "open", side_effect=FileNotFoundError("private/storage/key")
        ):
            response = self.client.post(
                reverse(self.view_name),
                {"file_id": str(self.file.pk)},
                content_type="application/json",
            )
        self.assertEqual(response.status_code, 404)
        self.assertNotIn(b"private/storage", response.content)

    def test_discovery_exposes_original_read_and_optional_upload_field(self) -> None:
        """Publish truthful read-only annotations and discoverable field input."""
        tools = {route.mcp_tool_name: route.mcp for route in router.get_mcp_routes()}
        read = tools["api_file_read"]
        self.assertTrue(read.read_only_hint)
        self.assertTrue(read.idempotent_hint)
        self.assertIn("file_id", read.get_input_schema()["properties"])
        self.assertIn(
            "field", tools["api_assistant_file_upload"].get_input_schema()["properties"]
        )


@override_settings(
    STORAGES={
        "default": {"BACKEND": "django.core.files.storage.InMemoryStorage"},
        "staticfiles": {
            "BACKEND": "django.contrib.staticfiles.storage.StaticFilesStorage"
        },
    }
)
class TestFileReadMcp(BloomerpMcpViewTestCase):
    """Exercise generic MCP transport with the same original-byte API contract."""

    view_name = "api_file_read"

    def prepare_file(self, scenario: McpRequestScenario) -> None:
        """Create synthetic in-memory content rather than using production records."""
        file = FileNode.objects.create(
            content=SimpleUploadedFile("mcp.txt", b"original mcp bytes"),
            kind="FILE",
            created_by=self.admin_user,
            updated_by=self.admin_user,
        )
        scenario.arguments["file_id"] = str(file.pk)

    def original_mcp_content(self, response: HttpResponse) -> bool:
        """Validate original base64 within the actual MCP structured-content envelope."""
        result = response.json()["result"]
        self.assertFalse(result.get("isError", False), result)
        self.assertEqual(
            base64.b64decode(result["structuredContent"]["content_base64"]),
            b"original mcp bytes",
        )
        return True

    def get_test_scenarios(self) -> list[McpRequestScenario]:
        """Verify permitted and denied MCP reads through the registered tool."""
        return [
            McpRequestScenario(
                name="MCP reads original bytes",
                user=self.admin_user,
                prepare=self.prepare_file,
                arguments={},
                expected=ExpectedResult(response_validators=self.original_mcp_content),
            ),
            McpRequestScenario(
                name="MCP denies another user's private upload",
                user=self.normal_user,
                prepare=self.prepare_file,
                arguments={},
                expected=ExpectedResult(response_validators=self.mcp_is_error()),
            ),
        ]

    def test_generic_mcp_upload_then_read(self) -> None:
        """Round-trip bytes through two actual MCP calls using their returned file ID."""
        self.client.force_login(self.admin_user)
        uploaded = self.client.post(
            **self._get_request_kwargs(
                McpRequestScenario(
                    name="upload",
                    arguments={
                        "filename": "hello.txt",
                        "content_base64": "aGVsbG8=",
                    },
                ),
                "api_assistant_file_upload",
            )
        )
        result = uploaded.json()["result"]
        self.assertFalse(result.get("isError", False), result)
        read = self.client.post(
            **self._get_request_kwargs(
                McpRequestScenario(
                    name="read",
                    arguments={
                        "file_id": result["structuredContent"]["file_id"],
                    },
                ),
                "api_file_read",
            )
        )
        result = read.json()["result"]
        self.assertFalse(result.get("isError", False), result)
        self.assertEqual(
            base64.b64decode(result["structuredContent"]["content_base64"]), b"hello"
        )

    @override_settings(BLOOMERP_AGENT_UPLOAD_MAX_BYTES=6)
    def test_oversized_mcp_upload_has_bounded_error(self) -> None:
        """Reject excessive encoded content without echoing it through JSON-schema errors."""
        self.client.force_login(self.admin_user)
        response = self.client.post(
            **self._get_request_kwargs(
                McpRequestScenario(
                    name="oversized upload",
                    arguments={
                        "filename": "hello.txt",
                        "content_base64": "a" * 1000,
                    },
                ),
                "api_assistant_file_upload",
            )
        )
        result = response.json()["result"]
        self.assertTrue(result["isError"])
        self.assertLess(len(response.content), 500)
        self.assertNotIn("a" * 1000, str(result))
        self.assertFalse(FileNode.objects.exists())
